<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\{Program,Testimonial,Gallery,SiteSetting}; use App\Services\ActivityLogger; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class ContentController extends Controller { private function model(string $type): string{return ['programs'=>Program::class,'testimonials'=>Testimonial::class,'gallery'=>Gallery::class][$type];} private function rules(string $type,bool $new=true):array{$base=['is_active'=>'sometimes|boolean','display_order'=>'sometimes|integer|min:0','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:5120'];return match($type){'programs'=>[...$base,'title'=>($new?'required':'sometimes').'|string|max:200','slug'=>($new?'required':'sometimes').'|alpha_dash|max:220|unique:programs,slug','short_description'=>($new?'required':'sometimes').'|string|max:500','description'=>'nullable|string','degree_type'=>($new?'required':'sometimes').'|string|max:120','duration'=>'nullable|string|max:120','eligibility'=>'nullable|string','is_featured'=>'sometimes|boolean'], 'testimonials'=>[...$base,'student_name'=>($new?'required':'sometimes').'|string|max:150','course_or_role'=>'nullable|string|max:150','quote'=>($new?'required':'sometimes').'|string|max:3000','rating'=>'nullable|integer|between:1,5','is_featured'=>'sometimes|boolean'], default=>[...$base,'title'=>($new?'required':'sometimes').'|string|max:200','description'=>'nullable|string|max:3000','alt_text'=>($new?'required':'sometimes').'|string|max:255']};} public function publicList(Request $r,string $type){$m=$this->model($type);$q=$m::where('is_active',true)->orderBy('display_order');if($type==='programs'&&$r->boolean('featured'))$q->where('is_featured',true);return response()->json(['success'=>true,'message'=>ucfirst($type).' retrieved.','data'=>$q->get()]);} public function program(string $slug){$p=Program::where('slug',$slug)->where('is_active',true)->firstOrFail();return response()->json(['success'=>true,'message'=>'Program retrieved.','data'=>$p]);} public function index(Request $r,string $type){$m=$this->model($type);return response()->json(['success'=>true,'message'=>'Content retrieved.','data'=>$m::withTrashed()->orderBy('display_order')->paginate(min((int)$r->get('per_page',20),100))]);} public function store(Request $r,string $type){$d=$r->validate($this->rules($type));$m=$this->model($type);if(empty($d['slug'])&&$type==='programs')$d['slug']=Str::slug($d['title']);if($r->hasFile('image'))$d['image_path']=$r->file('image')->store('uploads/'.$type,'public');unset($d['image']);$d['created_by']=$r->user()->id;$x=$m::create($d);ActivityLogger::log($r,$type.'_created',$type,$x->id,'Created '.$type);return response()->json(['success'=>true,'message'=>'Created.','data'=>$x],201);} public function show(string $type,int $id){$m=$this->model($type);return response()->json(['success'=>true,'message'=>'Content retrieved.','data'=>$m::withTrashed()->findOrFail($id)]);} public function update(Request $r,string $type,int $id){$m=$this->model($type);$x=$m::withTrashed()->findOrFail($id);$d=$r->validate($this->rules($type,false));if($type==='programs'&&isset($d['slug'])&&$m::where('slug',$d['slug'])->where('id','!=',$id)->exists())return response()->json(['success'=>false,'message'=>'Slug already exists.','errors'=>['slug'=>['Slug already exists.']]],422);$old=$x->image_path;if($r->hasFile('image'))$d['image_path']=$r->file('image')->store('uploads/'.$type,'public');unset($d['image']);$x->update($d);if(isset($d['image_path'])&&$old)Storage::disk('public')->delete($old);ActivityLogger::log($r,$type.'_updated',$type,$id,'Updated '.$type);return response()->json(['success'=>true,'message'=>'Updated.','data'=>$x->fresh()]);} public function destroy(Request $r,string $type,int $id){$m=$this->model($type);$x=$m::findOrFail($id);$x->delete();ActivityLogger::log($r,$type.'_deleted',$type,$id,'Deleted '.$type);return response()->noContent();} public function restore(string $type,int $id){$m=$this->model($type);$x=$m::onlyTrashed()->findOrFail($id);$x->restore();return response()->json(['success'=>true,'message'=>'Restored.','data'=>$x]);} public function reorder(Request $r,string $type){$d=$r->validate(['items'=>'required|array|max:100','items.*.id'=>'required|integer','items.*.display_order'=>'required|integer|min:0']);$m=$this->model($type);foreach($d['items'] as $item)$m::whereKey($item['id'])->update(['display_order'=>$item['display_order']]);return response()->json(['success'=>true,'message'=>'Reordered.','data'=>(object)[]]);} public function site(){return response()->json(['success'=>true,'message'=>'Site content retrieved.','data'=>SiteSetting::where('is_public',true)->pluck('value','key')]);} public function settings(){return response()->json(['success'=>true,'message'=>'Settings retrieved.','data'=>SiteSetting::orderBy('key')->get()]);} public function updateSettings(Request $r){$d=$r->validate(['settings'=>'required|array|max:50','settings.*.key'=>'required|string|max:100','settings.*.value'=>'nullable|string|max:10000','settings.*.type'=>'nullable|in:text,json,url','settings.*.is_public'=>'nullable|boolean']);foreach($d['settings'] as $s)SiteSetting::updateOrCreate(['key'=>$s['key']],$s);ActivityLogger::log($r,'settings_updated','site_settings',null,'Updated site settings');return $this->settings();}}
